<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$year=filter_var($_POST['academic_year']??null,FILTER_VALIDATE_INT);$number=filter_var($_POST['term_number']??null,FILTER_VALIDATE_INT);$name=trim((string)($_POST['name']??''));$start=(string)($_POST['starts_on']??'');$end=(string)($_POST['ends_on']??'');$current=isset($_POST['is_current']);$id=isset($_POST['term_id'])?filter_var($_POST['term_id'],FILTER_VALIDATE_INT):null;
$validDate=static function($d){if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))return false;$v=DateTimeImmutable::createFromFormat('!Y-m-d',$d);$e=DateTimeImmutable::getLastErrors();return $v&&$v->format('Y-m-d')===$d&&($e===false||(!$e['warning_count']&&!$e['error_count']));};
if($year===false||$year<2000||$year>2100||$number===false||$number<1||$number>3||$name===''||strlen($name)>60||!$validDate($start)||!$validDate($end)||$start>$end||$id===false||($id!==null&&$id<1)){$_SESSION['error']='Check the academic year, term number, name and dates.';header('Location: ../?page=academics&tab=terms');exit;}
$pdo=db();try{$pdo->beginTransaction();$schoolLock=$pdo->query('SELECT id FROM school_profile WHERE id=1 FOR UPDATE')->fetchColumn();if(!$schoolLock)throw new DomainException('School settings are missing. Restore the school profile before changing the term calendar.');if($id){$exists=$pdo->prepare('SELECT id FROM school_terms WHERE id=:id FOR UPDATE');$exists->execute(['id'=>$id]);if(!$exists->fetchColumn())throw new DomainException('Academic term not found. Refresh the term calendar and try again.');}if($current)$pdo->exec('UPDATE school_terms SET is_current=0');if($id){$stmt=$pdo->prepare('UPDATE school_terms SET academic_year=:year,term_number=:term,name=:name,starts_on=:start,ends_on=:end,is_current=:current WHERE id=:id');$stmt->execute(['year'=>$year,'term'=>$number,'name'=>$name,'start'=>$start,'end'=>$end,'current'=>$current,'id'=>$id]);$termId=(int)$id;$action='term.updated';}else{$stmt=$pdo->prepare('INSERT INTO school_terms (academic_year,term_number,name,starts_on,ends_on,is_current) VALUES (:year,:term,:name,:start,:end,:current)');$stmt->execute(['year'=>$year,'term'=>$number,'name'=>$name,'start'=>$start,'end'=>$end,'current'=>$current]);$termId=(int)$pdo->lastInsertId();$action='term.created';}$currentCount=(int)$pdo->query('SELECT COUNT(*) FROM school_terms WHERE is_current=1')->fetchColumn();if($currentCount>1)throw new DomainException('Only one term can be current. Correct the current term selection and try again.');audit_log($action,'school_terms',$termId,['year'=>$year,'term'=>$number,'is_current'=>$current]);$pdo->commit();$_SESSION['notice']='Academic term saved.';}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Term save failed: '.$e->getMessage());$_SESSION['error']=$e->getCode()==='23000'?'That academic year and term already exists.':'Could not save the academic term.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Term save failed: '.$e->getMessage());$_SESSION['error']=$e instanceof DomainException?$e->getMessage():'Could not save the academic term.';}
header('Location: ../?page=academics&tab=terms');exit;
